import json, random, subprocess, sys, string
rng = random.Random(4242)
lines = []
BASE = {"epoch":7,"node_count":2,"edges":[{"tail":0,"head":1,"capacity":4}],"commodities":[],"failed_edges":[],"budget":0}
for _ in range(60):
    kind = rng.randrange(8)
    if kind == 0:
        lines.append("".join(rng.choice(string.printable) for _ in range(rng.randrange(0,60))))
    elif kind == 1:
        lines.append(json.dumps(BASE)[:rng.randrange(0, len(json.dumps(BASE)))])
    elif kind == 2:
        lines.append(json.dumps({k: v for k, v in BASE.items() if rng.random() < 0.7}))
    elif kind == 3:
        d = dict(BASE); d[rng.choice(list(BASE))] = rng.choice([None, [], {}, "", 1.5, True, -1, 10**20, [1,2]])
        lines.append(json.dumps(d))
    elif kind == 4:
        lines.append(json.dumps(BASE) + " " * rng.randrange(0,5))
    elif kind == 5:
        lines.append("[" * rng.randrange(1,50) + "]" * rng.randrange(1,50))
    elif kind == 6:
        lines.append(json.dumps(BASE).replace('"budget":0', '"budget":%s' % rng.choice(["0.0","1e3","null","\"3\""])))
    else:
        lines.append(json.dumps({"epoch":7,"node_count":2,"edges":[{"tail":0,"head":1,"capacity":4}],"commodities":[{"source":0,"target":1,"demand":0,"paths":[[0]],"previous":[16]}],"failed_edges":[],"budget":0}))
data = ("\n".join(lines) + "\n").encode()
print("actual lines in data:", data.count(b"\n"))
p = subprocess.run([sys.executable,"/app/submission/planner.py"], input=data, capture_output=True, timeout=300)
print("out lines:", len(p.stdout.decode().splitlines()))
PYEOF
